using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.InputSystem;
using LWS.TruckHockey;
using LWS.TruckSports;
namespace LWS.TruckWallball {
public enum WallballMode {PlayerAI,SharedKeyboard,SeparateControllers,KeyboardController,AIVsAI,SharedController,Custom}
[DefaultExecutionOrder(-100)]public sealed class WallballMatch:MonoBehaviour {
 public const string SetupKey="TruckWallball.Setup.v1";
 public HockeyPlayer[] players={new HockeyPlayer{name="Blue",color=new Color(.15f,.8f,1),source=HockeySource.Keyboard,forward=Key.W,left=Key.A,back=Key.S,right=Key.D},new HockeyPlayer{name="Orange",color=new Color(1,.55f,.13f),source=HockeySource.AI,forward=Key.UpArrow,left=Key.LeftArrow,back=Key.DownArrow,right=Key.RightArrow}};
 public Key[] jumpKeys={Key.Space,Key.RightShift};public WallballMode mode;public WallballTruck[] trucks;public WallballAI[] agents;public WallballBall ball;public Collider floor,wall;public WallballMenus menus;public SportsSettings settings;public SportsFeedback feedback;public Renderer[] paint;
 public float halfWidth=8,courtLength=20;public readonly WallballRules rules=new WallballRules();public readonly SportsDeviceInput input=new SportsDeviceInput();
 public bool InMatch{get;private set;}public bool MenuOpen=>menus.Screen!=WallballScreen.Play;public int Revision{get;private set;}public int Replays{get;private set;}public int PhysicalReturns{get;private set;}public int LegalReturns{get;private set;}public string Notice{get;private set;}="FIRST TO 11 • WIN BY TWO";
 public readonly bool[] Armed=new bool[2];bool[] jumpHeld=new bool[2];int opening,lastEligible=-99,observedPoints;bool outgoingServe;float stalled;Material[] colors;readonly List<Material>[] cabPaint={new List<Material>(),new List<Material>()};
 public bool Ready(int i){var p=players[i];return p.source==HockeySource.AI||p.source==HockeySource.Keyboard&&Keyboard.current!=null&&Keyboard.current.enabled||p.controller&&p.pad!=null&&p.pad.added&&p.pad.enabled;}
 public bool DevicesReady=>ValidateOwnership(out _)&&Ready(0)&&Ready(1);public bool AllAI=>players[0].source==HockeySource.AI&&players[1].source==HockeySource.AI;
 public bool ValidateOwnership(out string reason){for(int i=0;i<2;i++){var p=players[i];if(p.source!=HockeySource.Keyboard)continue;var keys=new[]{p.forward,p.left,p.back,p.right,jumpKeys[i]};for(int k=0;k<keys.Length;k++){if(keys[k]==Key.None||keys[k]==Key.Escape){reason="Assign driving/jump keys; Escape is reserved.";return false;}for(int j=0;j<k;j++)if(keys[k]==keys[j]){reason="Duplicate gameplay key.";return false;}if(i==1&&players[0].source==HockeySource.Keyboard&&(keys[k]==players[0].forward||keys[k]==players[0].back||keys[k]==players[0].left||keys[k]==players[0].right||keys[k]==jumpKeys[0])){reason="Keyboard sources overlap.";return false;}}}
  var a=players[0];var b=players[1];if(a.controller&&b.controller&&a.pad!=null&&a.pad==b.pad&&(a.source==HockeySource.WholeController||b.source==HockeySource.WholeController||a.source==b.source)){reason="One owner per whole pad or separate stick/trigger.";return false;}reason="";return true;}
 void Awake(){Physics.IgnoreCollision(trucks[0].shape,trucks[1].shape);for(int i=0;i<2;i++)Physics.IgnoreCollision(trucks[i].shape,ball.shape);Freeze(true);colors=new Material[paint.Length];for(int i=0;i<paint.Length;i++){colors[i]=new Material(paint[i].sharedMaterial);paint[i].sharedMaterial=colors[i];}for(int i=0;i<2;i++)foreach(var r in trucks[i].GetComponentsInChildren<MeshRenderer>())if(r.name=="Cab"&&r!=paint[i])foreach(var material in r.materials)cabPaint[i].Add(material);}
 void Start(){foreach(var t in trucks)t.CacheShapes();BindTruckPairs();Load();Dirty();menus.Show(WallballScreen.Setup);}void OnEnable(){InputSystem.onDeviceChange+=DeviceChanged;}void OnDisable(){InputSystem.onDeviceChange-=DeviceChanged;feedback.StopAll();}void OnDestroy(){if(colors!=null)foreach(var c in colors)Destroy(c);foreach(var list in cabPaint)foreach(var c in list)Destroy(c);Time.timeScale=1;}
 public void Dirty(){Revision++;menus?.Dirty();}public void Gate(){foreach(var p in players)p.released=false;for(int i=0;i<2;i++){trucks[i].Stop();jumpHeld[i]=JumpHeld(i);}menus?.Gate();}
 public void Configure(WallballMode selection){mode=selection;for(int i=0;i<2;i++){var p=players[i];var old=p.source;p.source=selection==WallballMode.AIVsAI?HockeySource.AI:selection==WallballMode.SharedKeyboard?HockeySource.Keyboard:selection==WallballMode.SeparateControllers?HockeySource.WholeController:selection==WallballMode.SharedController?(i==0?HockeySource.LeftStick:HockeySource.RightStick):selection==WallballMode.KeyboardController?(i==0?HockeySource.Keyboard:HockeySource.WholeController):i==0?HockeySource.Keyboard:HockeySource.AI;if(old!=p.source)p.pad=null;}Gate();Dirty();Save();}
 public bool Assign(int i,Gamepad pad){if(i<0||i>1||!players[i].controller||pad==null||!pad.added||!pad.enabled)return false;var old=players[i].pad;players[i].pad=pad;if(!ValidateOwnership(out _)){players[i].pad=old;return false;}input.Forget(pad);Gate();Dirty();Save();return true;}
 public void Unassign(int i){players[i].pad=null;Gate();Dirty();}public void CycleSource(int i){mode=WallballMode.Custom;players[i].source=(HockeySource)(((int)players[i].source+1)%5);players[i].pad=null;Gate();Dirty();Save();}
 public Vector2 Drive(int i){var p=players[i];if(!Ready(i)||p.source==HockeySource.AI)return Vector2.zero;if(p.source==HockeySource.Keyboard)return new Vector2((SportsDeviceInput.KeyHeld(p.right)?1:0)-(SportsDeviceInput.KeyHeld(p.left)?1:0),(SportsDeviceInput.KeyHeld(p.forward)?1:0)-(SportsDeviceInput.KeyHeld(p.back)?1:0));if(p.source==HockeySource.LeftStick||p.source==HockeySource.RightStick){var v=p.source==HockeySource.LeftStick?p.pad.leftStick.ReadValue():p.pad.rightStick.ReadValue();return new Vector2(Mathf.Abs(v.x)<.16f?0:v.x,Mathf.Abs(v.y)<.16f?0:v.y);}var stick=p.pad.leftStick.ReadValue();float gas=p.pad.rightTrigger.ReadValue()-p.pad.leftTrigger.ReadValue();return new Vector2(Mathf.Abs(stick.x)<.16f?0:stick.x,Mathf.Abs(gas)<.1f?0:gas);}
 public bool JumpHeld(int i){if(!Ready(i))return false;var p=players[i];return p.source==HockeySource.Keyboard?SportsDeviceInput.KeyHeld(jumpKeys[i]):p.source==HockeySource.LeftStick?p.pad.leftTrigger.ReadValue()>.5f:p.source==HockeySource.RightStick?p.pad.rightTrigger.ReadValue()>.5f:p.source==HockeySource.WholeController&&p.pad.buttonSouth.isPressed;}
 public bool Neutral(int i)=>Ready(i)&&(players[i].source==HockeySource.AI||Drive(i).sqrMagnitude<.01f&&!JumpHeld(i)&&(!players[i].controller||!players[i].pad.startButton.isPressed&&!players[i].pad.buttonSouth.isPressed));
 public string Controls(int i){var p=players[i];return p.source==HockeySource.AI?"AI • "+p.difficulty:p.source==HockeySource.Keyboard?p.forward+"/"+p.left+"/"+p.back+"/"+p.right+" • "+jumpKeys[i]+" JUMP":p.source==HockeySource.LeftStick?"LEFT STICK drives • LT JUMP":p.source==HockeySource.RightStick?"RIGHT STICK drives • RT JUMP":"LEFT STICK steers • RT/LT drive/brake • SOUTH JUMP";}
 void DeviceChanged(InputDevice device,InputDeviceChange change){Dirty();foreach(var p in players)if(p.controller&&p.pad==device){input.Forget((Gamepad)device);Gate();if(InMatch&&rules.Phase!=WallballPhase.Finished&&(change==InputDeviceChange.Removed||change==InputDeviceChange.Disconnected||change==InputDeviceChange.Disabled))Pause(true);break;}}
 public bool StartMatch(bool rematch=false){if(!DevicesReady){menus.Show(WallballScreen.Join);return false;}opening=rematch?1-opening:0;Save();InMatch=true;Replays=PhysicalReturns=LegalReturns=observedPoints=0;rules.Start(opening);ResetServe();Gate();menus.Show(WallballScreen.Play);Time.timeScale=1;Notice=players[opening].name+" opens • FIRST TO 11, WIN BY TWO";return true;}
 void Freeze(bool value){foreach(var t in trucks){if(value&&!t.body.isKinematic)t.body.linearVelocity=t.body.angularVelocity=Vector3.zero;t.body.isKinematic=value;t.Stop();foreach(var w in t.wheels)w.enabled=!value;if(!value){foreach(var w in t.wheels)w.WakeFromSleep();t.CacheShapes();}}if(value&&!ball.body.isKinematic)ball.body.linearVelocity=ball.body.angularVelocity=Vector3.zero;ball.body.isKinematic=value;if(!value)BindTruckPairs();}
 public void ResetServe(){Freeze(true);float x=rules.Server==0?-3:3;ball.body.position=new Vector3(x,.55f,-5.7f);ball.body.rotation=Quaternion.identity;for(int i=0;i<2;i++){trucks[i].ResetBody(new Vector3(x,.36f,i==rules.Server?-8:-12));colors[i].color=players[i].color;foreach(var material in cabPaint[i])material.color=players[i].color;}foreach(var a in agents)a.ResetPlan();ball.ClearContacts();lastEligible=-99;stalled=0;ArmContacts();feedback.StopAll();Physics.SyncTransforms();}
 public void Pause(bool disconnected=false){if(!InMatch||rules.Phase==WallballPhase.Finished)return;rules.Pause();Time.timeScale=0;Gate();feedback.StopAll();menus.Show(disconnected?WallballScreen.Disconnect:WallballScreen.Pause);}
 public void Resume(){if(!DevicesReady){Pause(true);return;}rules.Resume();Time.timeScale=1;Gate();menus.Show(WallballScreen.Play);}public void ChangeSetup(){InMatch=false;Time.timeScale=1;Freeze(true);feedback.StopAll();menus.Show(WallballScreen.Setup);}
 public void Replay(string reason){if(!rules.Active)return;Replays++;rules.Replay();ResetServe();Notice="RALLY REPLAY • SCORE UNCHANGED • "+reason;Debug.Log("WB_NEUTRAL_REPLAY "+reason);}
 public void RecoverTruck(int i){for(int k=0;k<4;k++){var p=new Vector3((i==0?-1:1)*(3+k%2*2),.36f,-12-k/2*3);if(Vector3.Distance(p,ball.body.position)<2.5f)continue;trucks[i].ResetBody(p);agents[i].ResetPlan();Notice=players[i].name+" recovered • Rally and score retained";return;}}
 // Eligibility changes only collision ownership. Neither movement nor held-input state is gated.
 public void BindTruckPairs(){foreach(var a in trucks[0].CollisionShapes??new[]{(Collider)trucks[0].shape})foreach(var b in trucks[1].CollisionShapes??new[]{(Collider)trucks[1].shape})if(a!=null&&b!=null)Physics.IgnoreCollision(a,b);}
 public void ArmContacts(){int eligible=rules.Active?rules.Eligible:-1;if(eligible!=lastEligible){Armed[0]=Armed[1]=false;lastEligible=eligible;}for(int i=0;i<2;i++){var shapes=trucks[i].CollisionShapes;if(shapes==null)shapes=new[]{(Collider)trucks[i].shape};if(eligible==i&&!Armed[i]){bool clear=true;foreach(var c in shapes)if(c!=null&&c.enabled&&Vector3.Distance(trucks[i].PhysicalClosestPoint(c,ball.body.position),ball.body.position)<=ball.radius+.06f){clear=false;break;}Armed[i]=clear;}foreach(var c in shapes)if(c!=null)Physics.IgnoreCollision(c,ball.shape,eligible!=i||!Armed[i]);}}
 public bool Strike(int slot,Vector3 normal,Vector3 relative){if(!Armed[slot]||rules.Eligible!=slot||!rules.Active)return false;bool serve=rules.Phase==WallballPhase.Serving;if(!rules.Strike(slot))return false;outgoingServe=serve;trucks[slot].RecordHit();if(!serve)PhysicalReturns++;stalled=0;
  // Once per actual eligible contact: preserve PhysX response, add bounded normal lift/strength.
  // Direction follows contact/truck motion, never a target point on the wall.
  var planar=new Vector3(normal.x,0,normal.z);if(planar.sqrMagnitude<.04f)planar=trucks[slot].transform.forward;else planar.Normalize();float closing=Mathf.Abs(Vector3.Dot(relative,normal));var v=ball.body.linearVelocity;v+=planar*Mathf.Clamp(closing*.2f,.6f,2);v.y=Mathf.Clamp(v.y,6.2f,8.5f);ball.body.linearVelocity=Vector3.ClampMagnitude(v,ball.maxSpeed);Armed[0]=Armed[1]=false;ArmContacts();Notice=players[slot].name+" hit • Reach the wall before the floor";Pulse(slot,.1f,.08f);Debug.Log("WB_PHYSICAL_STRIKE slot="+slot+" shot="+rules.Shots+" serve="+serve+" velocity="+ball.body.linearVelocity);return true;}
 public void Wall(bool valid){int before=rules.LegalWalls;rules.Wall(valid);if(rules.LegalWalls>before&&!outgoingServe)LegalReturns++;ArmContacts();if(rules.Phase==WallballPhase.Receiving)Notice=players[rules.Eligible].name+" TO HIT • Volley or one bounce";ResolvePoint();}
 public void Floor(){var p=ball.body.position;if(Mathf.Abs(p.x)>halfWidth||p.z< -courtLength)rules.Out();else rules.Floor();if(rules.Phase==WallballPhase.Receiving&&rules.Bounces==1)Notice="FIRST BOUNCE • "+players[rules.Eligible].name+" TO HIT";ResolvePoint();}
 public void ResolvePoint(){if(rules.Points==observedPoints)return;observedPoints=rules.Points;Freeze(true);ArmContacts();Notice=rules.Reason+" • POINT TO "+players[rules.PointWinner].name;feedback.Play(6,0,true);Debug.Log("WB_POINT "+Notice+" score="+rules.Score[0]+":"+rules.Score[1]);if(rules.Phase==WallballPhase.Finished){menus.Show(WallballScreen.Result);feedback.StopMotors();menus.Celebrate();feedback.Play(7,0,true);Time.timeScale=0;}}
 public void Pulse(int i,float strength,float duration){feedback.Pulse(players[i].controller?players[i].pad:null,strength,duration);}
 void Update(){input.Sample();if(menus.Screen==WallballScreen.Join||menus.Screen==WallballScreen.Disconnect)foreach(var pad in Gamepad.all)if(input.Down(pad,2))for(int i=0;i<2;i++)if(players[i].controller&&!Ready(i)&&Assign(i,pad)){if(players[i].source==HockeySource.WholeController)break;}
  bool pause=SportsDeviceInput.KeyDown(Key.Escape);foreach(var p in players)if(p.controller&&input.Down(p.pad,4))pause=true;if(AllAI)foreach(var pad in Gamepad.all)pause|=input.Down(pad,4);if(pause){if(menus.Screen==WallballScreen.Play)Pause();else menus.Back();return;}if(!InMatch||MenuOpen)return;
  for(int i=0;i<2;i++){if(players[i].source==HockeySource.AI)continue;if(!Ready(i)){Pause(true);return;}bool jump=JumpHeld(i),pressed=jump&&!jumpHeld[i];jumpHeld[i]=jump;if(!players[i].released){trucks[i].Stop();if(Neutral(i))players[i].released=true;continue;}if(rules.Active){var drive=Drive(i);drive.x*=settings.sensitivity;trucks[i].Control(drive,pressed);}}}
 void FixedUpdate(){if(!InMatch||MenuOpen)return;var before=rules.Phase;rules.Tick(Time.fixedDeltaTime);ResolvePoint();if(before==WallballPhase.Point&&rules.Phase==WallballPhase.Countdown){ResetServe();Notice=players[rules.Server].name+" serves";}else if(before==WallballPhase.Countdown&&rules.Phase==WallballPhase.Serving){Freeze(false);ball.ClearContacts();Notice=players[rules.Server].name+" TO SERVE • 25 SECONDS";feedback.Play(0,0,true);}
  if(!rules.Active)return;ArmContacts();var p=ball.body.position;if(float.IsNaN(p.x)||p.y< -1){Replay("Ball simulation recovered");return;}if(Mathf.Abs(p.x)>halfWidth+ball.radius||p.z< -courtLength-ball.radius||p.y>9||p.z>.6f&&(Mathf.Abs(p.x)>halfWidth-.2f||p.y>7.5f)){rules.Out();ResolvePoint();return;}if(p.z>.6f){Replay("Missing wall contact");return;}
  if(rules.Phase!=WallballPhase.Serving){stalled=ball.body.linearVelocity.sqrMagnitude<.01f?stalled+Time.fixedDeltaTime:0;if(stalled>4){Replay("Ball stopped without a resolving contact");return;}}for(int i=0;i<2;i++)if(trucks[i].body.position.y< -2||Mathf.Abs(trucks[i].body.position.x)>halfWidth+2||trucks[i].body.position.z< -courtLength-2)RecoverTruck(i);}
 [Serializable]sealed class Saved{public WallballMode mode;public Slot[] slots;}[Serializable]sealed class Slot{public string name;public Color color;public HockeySource source;public HockeyDifficulty difficulty;public int pad;public Key jump;}
 public void Save(){var s=new Saved{mode=mode,slots=new Slot[2]};for(int i=0;i<2;i++){var p=players[i];s.slots[i]=new Slot{name=p.name,color=p.color,source=p.source,difficulty=p.difficulty,pad=p.pad?.deviceId??-1,jump=jumpKeys[i]};}PlayerPrefs.SetString(SetupKey,JsonUtility.ToJson(s));PlayerPrefs.Save();}
 void Load(){try{if(!PlayerPrefs.HasKey(SetupKey))return;var s=JsonUtility.FromJson<Saved>(PlayerPrefs.GetString(SetupKey));if(s?.slots==null||s.slots.Length!=2)return;mode=s.mode;for(int i=0;i<2;i++){var p=players[i];var a=s.slots[i];p.name=string.IsNullOrWhiteSpace(a.name)?"Player "+(i+1):a.name;p.color=a.color;p.source=a.source;p.difficulty=a.difficulty;p.pad=InputSystem.GetDeviceById(a.pad) as Gamepad;if(a.jump!=Key.None)jumpKeys[i]=a.jump;}}catch(Exception){Debug.LogWarning("Wallball setup invalid; defaults retained.");}}
}
}
